CREATE UNIQUE INDEX profiles_org_sap_unique ON public.profiles(organization_id,sap_id) WHERE sap_id IS NOT NULL;
CREATE TABLE public.personnel_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), requested_number text NOT NULL CHECK(requested_number ~ '^[0-9]{7,8}$'), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), decided_by uuid, decided_at timestamptz);
GRANT SELECT, INSERT ON public.personnel_requests TO authenticated; GRANT ALL ON public.personnel_requests TO service_role;
ALTER TABLE public.personnel_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY personnel_requests_read ON public.personnel_requests FOR SELECT TO authenticated USING(public.can_see(user_id));
CREATE POLICY personnel_requests_insert ON public.personnel_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending' AND decided_by IS NULL AND decided_at IS NULL AND public.my_organization() IS NOT NULL);
CREATE UNIQUE INDEX personnel_one_pending ON public.personnel_requests(user_id) WHERE status='pending';
CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles(id), new_devices boolean NOT NULL DEFAULT false, manual_punches boolean NOT NULL DEFAULT false);
GRANT SELECT, INSERT, UPDATE ON public.notification_preferences TO authenticated; GRANT ALL ON public.notification_preferences TO service_role;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_preferences_own ON public.notification_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND (public.has_role(auth.uid(),'manager') OR public.has_role(auth.uid(),'admin')));
CREATE OR REPLACE FUNCTION public.decide_personnel_request(_id uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE req public.personnel_requests; BEGIN SELECT * INTO req FROM public.personnel_requests WHERE id=_id FOR UPDATE; IF req.id IS NULL OR req.status<>'pending' THEN RAISE EXCEPTION 'Žiadosť nie je dostupná'; END IF; IF NOT(public.same_organization(req.user_id) AND (public.has_role(auth.uid(),'admin') OR public.is_manager_of(req.user_id))) THEN RAISE EXCEPTION 'Nedostatočné oprávnenie'; END IF; IF _approve THEN UPDATE public.profiles SET sap_id=req.requested_number WHERE id=req.user_id; END IF; UPDATE public.personnel_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decided_by=auth.uid(),decided_at=now() WHERE id=_id; INSERT INTO public.audit_log(actor,action,target,details) VALUES(auth.uid(),'personnel_request_decided',req.user_id::text,jsonb_build_object('approved',_approve)); END $$;
REVOKE ALL ON FUNCTION public.decide_personnel_request(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_personnel_request(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_account_event(_target uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT(public.same_organization(_target) AND public.has_role(auth.uid(),'admin')) OR _action NOT IN ('employee_provisioned','employee_password_reset') THEN RAISE EXCEPTION 'Nedostatočné oprávnenie'; END IF; INSERT INTO public.audit_log(actor,action,target) VALUES(auth.uid(),_action,_target::text); END $$;
REVOKE ALL ON FUNCTION public.audit_account_event(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.audit_account_event(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; org_name text; invite text; number text; BEGIN org_name:=btrim(COALESCE(NEW.raw_user_meta_data->>'organization_name','')); invite:=btrim(COALESCE(NEW.raw_user_meta_data->>'invite_code','')); number:=NULLIF(NEW.raw_user_meta_data->>'sap_id',''); IF org_name<>'' AND invite<>'' THEN RAISE EXCEPTION 'Vyberte registráciu firmy alebo pozvanie'; END IF; IF org_name<>'' THEN IF length(org_name) NOT BETWEEN 2 AND 160 THEN RAISE EXCEPTION 'Neplatný názov organizácie'; END IF; INSERT INTO public.organizations(name,created_by) VALUES(org_name,NEW.id) RETURNING id INTO org; INSERT INTO public.organization_settings SELECT org,s.* FROM public.settings s; INSERT INTO public.organization_codes SELECT org,c.* FROM public.absence_codes c; INSERT INTO public.organization_holidays SELECT org,h.* FROM public.holidays h; INSERT INTO public.organization_invites(organization_id) VALUES(org); ELSE SELECT organization_id INTO org FROM public.organization_invites WHERE code=invite; IF org IS NULL THEN RAISE EXCEPTION 'Neplatný pozývací kód organizácie'; END IF; IF number IS NULL THEN RAISE EXCEPTION 'Zadajte osobné číslo'; END IF; END IF; INSERT INTO public.profiles(id,organization_id,sap_id) VALUES(NEW.id,org,number); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'employee'); IF org_name<>'' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin'),(NEW.id,'manager'); END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.audit_personnel_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_log(actor,action,target) VALUES(auth.uid(),'personnel_change_requested',NEW.user_id::text); RETURN NEW; END $$;
CREATE TRIGGER personnel_request_audit AFTER INSERT ON public.personnel_requests FOR EACH ROW EXECUTE FUNCTION public.audit_personnel_request();